/** Points `origin` at the forge's host, from which the project's forge is found. */
const setForge = (host: "github.com" | "gitlab.com") => {
  try {
    git(repo, "remote", "remove", "origin");
  } catch {
    // No origin yet.
  }
  git(repo, "remote", "add", "origin", `https://${host}/acme/shop.git`);
};
